use std::{env,fs,io::{self,Write}};use spore_core::{creature_skin_sse2_field_v1::{evaluate,SnapshotAdmission},creature_generated_skin_kernel_v1::Lane,creature_generated_skin_grid_query_v1::CELL_COUNT,native_sse::Policy};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),1988);let v:Vec<u32>=b.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();let mut out=Vec::new();for c in v.chunks_exact(71){let n=c[14] as usize;assert!(n<=2);let mut records=Vec::new();for r in 0..n {let lanes=std::array::from_fn(|i|{let x=15+(r*4+i)*7;Lane{center:[f32::from_bits(c[x]),f32::from_bits(c[x+1]),f32::from_bits(c[x+2])],cutoff:f32::from_bits(c[x+3]),scale:f32::from_bits(c[x+4]),coefficient:f32::from_bits(c[x+5]),key:c[x+6]}});records.push(lanes);}let mut cells:[Option<&[[Lane;4]]>;CELL_COUNT]=[None;CELL_COUNT];if n>0{cells[c[13] as usize]=Some(&records);}let point=std::array::from_fn(|i|f32::from_bits(c[i]));let origin=std::array::from_fn(|i|f32::from_bits(c[4+i]));let scale=std::array::from_fn(|i|f32::from_bits(c[8+i]));let v=evaluate(point,origin,scale,f32::from_bits(c[12]),&cells,Policy::Mxcsr1f80,SnapshotAdmission).unwrap();assert_eq!(v.address.cell,c[13] as usize);out.extend(v.value.to_bits().to_le_bytes());}io::stdout().write_all(&out).unwrap();}
